INSERT INTO public.pattern_library (dimension, key, label, template, why, industries, source) VALUES
('hook','question','Direct question','open with a direct question the audience is already asking','Mirrors the viewer''s own thought, so they stay for the answer.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','stat','Specific number','open with one specific number or fact from the brand''s own context','Specific data feels objective and breaks expectations.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','bold_claim','Bold claim','open with a confident, slightly provocative claim, then back it up in the next line','Creates tension the viewer wants resolved.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','story','Story moment','open with a short real-feeling moment or scene, then the lesson','Narrative starts at tension, so viewers engage emotionally.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','how_to','How-to promise','promise a clear how-to and deliver concrete steps','Clear scope lowers the cost of staying.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','myth_bust','Myth bust','name a common myth, then correct it','Cognitive dissonance: the viewer wants to settle it.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','list','Numbered list','numbered list of quick, useful points; state the count in the first line','Odd numbers and a clear scope feel curated.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','contrarian','Contrarian','challenge a common habit or belief in the industry, then give the better way','Conflict with an existing belief drives engagement.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','before_after','Before and after','contrast the problem state with the improved state, worst state first','Fast visible payoff.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','behind_scenes','Behind the scenes','show how the work actually gets done, in a human voice','Unpolished process builds trust.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','customer_voice','Customer voice','speak in the audience''s own words about their problem (no invented quotes or names)','Instant recognition.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','offer','Offer first','lead with the offer or next step and why now','Clear value, clear deadline.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','pov','POV','open with ''POV:'' and put the viewer inside a relatable moment from their day','Relatable scenes get sent to friends.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','mistake','Biggest mistake','name one common mistake people make with this product or service, then the fix (no fear tactics)','Fear of error creates a pause.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','if_you','If you are...','open with ''If you are [specific person in a specific situation]...'' so the right viewer feels called out','Personal relevance beats broad appeal.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','unpopular_opinion','Unpopular opinion','state an honest, mild opinion most in this industry would not say out loud, then explain it','Disagreement drives comments.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','one_thing','One thing','promise one single thing to know or do, then deliver exactly that','Single promise, no friction.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','whats_inside','What is inside','show what is inside or included, piece by piece, like unboxing','Piece-by-piece reveal holds attention.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','honest_truth','Honest truth','say something plainly honest about price, effort or limits that builds trust','Honesty is rare and memorable.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','right_now','Right now','tie the post to this season, week or moment and why it matters now','Timeliness raises urgency.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','curiosity_gap','Curiosity gap','tease a surprising answer, hold it back for a beat: ''Only people who [result] know to [action], and it is [surprise]''','An open loop is uncomfortable until closed.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','shocking_stat','Shocking stat','''[Specific %] of [group] [negative outcome]. The ones who do not [differentiating action].'' Use only numbers the brand can stand behind','Specific data forces the viewer to recalibrate.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','transformation','Transformation','''[Time] ago [starting point]. Today [result]. One change made the difference.'' Only real results','Social proof plus curiosity about the path.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','direct_command','Direct command','''[Verb] this [urgency cue] before [event or deadline].'' Only when the deadline is real','Authority and urgency skip evaluation.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','list_promise','List promise','''[Odd number] [things] that [benefit] in [time or cost saved].''','Expectation management lowers friction.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','story_opener','Story opener','start at the dramatic point: ''I was about to [action]... then [turning point]''','Starting in tension beats starting at the beginning.',ARRAY[]::text[],'Short-form hook psychology guides (DEV Community, 2026)'),
('hook','stop_if','Stop if you...','''Stop scrolling if you want [specific goal].'' The goal must be specific to this brand''s audience','Speaks to a goal, prompting a pause.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','hidden_tip','Hidden tip','''The [thing] nobody tells you about [topic]...'' then one real, concrete tip','Promises insider knowledge.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','right_way','The right way','''The right way to [common task]'' when most people do it wrong; show the correct version','Suggests the viewer may be doing it wrong.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','years_lesson','Years in seconds','''[X] years of [work] taught me this'' then one lesson, only if the brand''s years are real','Compresses experience into a quick takeaway.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','does_this_happen','Does this happen to you','show a familiar annoying scene in one second, then ''Does this happen to you?''','Instant recognition.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','i_tested','I tested it','''I tested [thing] and here is what happened'' only when the brand really did, with the real result','Results build credibility.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','must_watch_for','Must-watch for','''Must watch if you are a [specific audience]''','Signals the content is made for them.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','quick_method','Quick method','''A quick way to [goal] without [pain]''','Fast, actionable promise.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','wait_for_it','Wait for it','tease the payoff in one line, deliver it in the final seconds so people watch to the end','Delayed payoff lifts completion rate.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','what_x_gets_you','What this price gets you','''What Rs [amount] gets you at [brand]'' then show the real items','Concrete price framing is sendable.',ARRAY[]::text[],'Founder''s reference reels and posts, Nov 2026'),
('hook','vs_compare','This vs that','put two options side by side (''[A] vs [B]''), say which suits whom and why','Comparison invites opinions.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','red_green_flag','Red flag / green flag','''Red flag: [bad sign]. Green flag: [good sign]'' when choosing this kind of product or service','Checklist framing is saved for later.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','signs_you_need','Signs you need','''3 signs you need [product or service]'' with honest, non-scary signs','Helps viewers self-diagnose.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','stop_doing','Stop doing','''Stop doing [common habit]. Do this instead.'' Frame as a better way, not a scolding','Flipped from how-to, increases attention.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','ranked_picks','Ranked picks','''[N] [things] that replace [expensive or annoying thing]'', numbered, each with one line why','Numbered picks are saved and sent.',ARRAY[]::text[],'Founder''s reference reels and posts, Nov 2026'),
('hook','by_the_numbers','By the numbers','lead with the brand''s real numbers (orders, years, pieces, customers) as one big figure','A big number is a visual stop sign.',ARRAY[]::text[],'Founder''s reference reels and posts, Nov 2026'),
('hook','question_to_answer','Answer a comment','''Someone asked: [real customer question]'' then answer in the same video','Answering real questions builds trust and series.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','headline_react','Headline reaction','put a real, relevant news or rule change in caps on the first frame, then one honest opinion','News framing earns a stop.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','cost_reveal','Cost reveal','''What it really costs to [make or do thing]'' and break down real costs','Transparency is rare and shareable.',ARRAY[]::text[],'LOVIZA editorial'),
('hook','process_asmr','Process close-up','open on a satisfying close-up of the work (hands, tools, materials) with no talking for 2 seconds','Satisfying visuals stop the scroll without words.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('hook','hinglish_dost','Dost talk (Hinglish)','open in casual Hinglish as if talking to a friend: ''Yaar, ye galti mat karna...''','Native tone feels human, not like an ad.',ARRAY[]::text[],'Founder''s reference reels and posts, Nov 2026'),
('hook','galat_stamp','GALAT stamp','state the myth, then stamp it wrong (''Ye galat hai'') with a visual stamp, then the right way','Strong visual verdict inside two seconds.',ARRAY[]::text[],'Founder''s reference reels and posts, Nov 2026'),
('hook','settings_secret','One setting','''There is one setting/step most people skip'' then show exactly where','Specific and actionable; people screenshot it.',ARRAY[]::text[],'Founder''s reference reels and posts, Nov 2026'),
('hook','numbers_ladder','Ladder of numbers','show a count-up or ladder (0 to 100, Rs X to Rs Y) with the story of each step','Progress visuals keep eyes moving.',ARRAY[]::text[],'Short-form editing practice'),
('format','pov_skit','POV micro-skit','on-screen text names a specific relatable situation, then a short reaction; cut on the reaction','Relatable and sendable.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','headline_reenact','Headline reenactment','a real headline in caps as first frame, play both sides with hard cuts, end with one-sentence opinion','News hooks plus personality.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','serial_episode','Serialised episode','same shot, light and caption stem every time, numbered ''Day 12'', only the subject changes','Builds a habit and a reason to follow.',ARRAY['product_brand','food','local_service']::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','micro_lesson','Micro-lesson','8-12 seconds, one small idea, with text overlays; wrong version first, right version on the beat','Short and educational is saved.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','before_after_reveal','Before and after reveal','open on the worst state with a number or question, fast process cuts, hold on the result, end with a question','Visible transformation.',ARRAY['local_service','home_space','product_brand']::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','shop_tour','Shop tour','entrance to counter to workspace in 15 seconds, one line per stop','Shows the real place; builds local trust.',ARRAY['food','product_brand','local_service']::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','day_in_life','Day in the life','opening, busiest hour and closing in quick cuts with timestamps','Backstage feels personal.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','product_drop','Product drop teaser','close-ups, a countdown and a reveal; say the date','Anticipation lifts follows.',ARRAY['product_brand','food']::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','customer_story','Customer story','customer''s problem, what we did, their result, in about 15 seconds; real, permitted stories only','Real proof.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','comment_reply','Reply to a comment','show the real question as a sticker, answer on camera or with text scenes','Social proof and an endless idea source.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','reaction','Reaction','react to a myth, a trend or the brand''s own old post','Opinion plus personality.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','mini_case','Mini case study','problem, solution, result with one number, about 15 seconds','Compact proof.',ARRAY['b2b','education','local_service']::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','trend_remix','Trend with a twist','use a trending format with the brand''s own subject; never copy the creator''s words','Rides existing demand.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','myth_vs_fact','Myth vs fact','stamp the myth as wrong, show the right way side by side, finish with what to do now','Verdict plus utility.',ARRAY[]::text[],'Founder''s reference reels and posts, Nov 2026'),
('format','step_by_step','Step by step','3-5 steps, one screen each, works with the sound off','Clear sequence, saved for later.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','settings_walkthrough','Settings walkthrough','one thing people get wrong, exact steps to fix it, what changes after','Actionable and screenshot-worthy.',ARRAY['b2b','education']::text[],'Founder''s reference reels and posts, Nov 2026'),
('format','ranked_picks','Ranked picks','a numbered set of picks, each with one line of why; state the count in the first scene','Lists are saved.',ARRAY[]::text[],'Founder''s reference reels and posts, Nov 2026'),
('format','doodle_story','Doodle story','one real moment as a story, a single number at the turning point, plain light scenes','Story plus a number.',ARRAY[]::text[],'Founder''s reference reels and posts, Nov 2026'),
('format','unboxing_inside','What is inside','reveal items one by one with price or use','Piece-by-piece reveal.',ARRAY['product_brand','food']::text[],'LOVIZA editorial'),
('format','process_cut','Making of','raw material to finished piece in 8-15 seconds, hands visible, timestamped steps','Satisfying process content is rewatched.',ARRAY['product_brand','food']::text[],'Short-form editing practice'),
('format','ugc_showcase','Customer showcase','feature a customer''s own photo or video with permission, add one line of context','Social proof.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','founder_story','Founder story','why it started, one struggle, what keeps going; first person, plain words','People follow people.',ARRAY[]::text[],'Public 2026 reel guides (Opus Pro, UpGrow, SocialPilot, Async, Buffer)'),
('format','faq_series','FAQ series','one real customer question per reel, numbered, same layout','Searchable and repeatable.',ARRAY['local_service','education','b2b']::text[],'LOVIZA editorial'),
