-- Pattern Library: reusable, brand-neutral patterns behind viral short-form content
-- (hooks, formats, angles per industry, pacing, captions, CTAs, endings, audio, platform signals, India rules).
-- Seeded from src/lib/pattern-library.ts. 'weight' is raised or lowered later from each brand's measured results.

CREATE TABLE IF NOT EXISTS public.pattern_library (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  dimension text NOT NULL,
  key text NOT NULL,
  label text NOT NULL,
  template text NOT NULL,
  why text NOT NULL DEFAULT '',
  industries text[] NOT NULL DEFAULT '{}',
  source text NOT NULL DEFAULT '',
  weight numeric NOT NULL DEFAULT 1,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (dimension, key)
);

ALTER TABLE public.pattern_library ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Signed-in users read patterns" ON public.pattern_library;
CREATE POLICY "Signed-in users read patterns" ON public.pattern_library
  FOR SELECT TO authenticated USING (true);

ON CONFLICT (dimension, key) DO UPDATE SET
  label = EXCLUDED.label, template = EXCLUDED.template, why = EXCLUDED.why,
  industries = EXCLUDED.industries, source = EXCLUDED.source, updated_at = now();

NOTIFY pgrst, 'reload schema';
